typedef struct {
  size_t line;
  size_t column;
  size_t offset;
} GumboSourcePosition;

typedef struct {
  /** A pointer to the beginning of the string. `NULL` if `length == 0`. */
  const char* data;

  /** The length of the string fragment, in bytes (may be zero). */
  size_t length;
} GumboStringPiece;

typedef struct {
  void** data;
  unsigned int length;
  unsigned int capacity;
} GumboVector;

typedef enum {
  GUMBO_ATTR_NAMESPACE_NONE,
  GUMBO_ATTR_NAMESPACE_XLINK,
  GUMBO_ATTR_NAMESPACE_XML,
  GUMBO_ATTR_NAMESPACE_XMLNS,
} GumboAttributeNamespaceEnum;

typedef struct {
  GumboAttributeNamespaceEnum attr_namespace;
  const char* name;
  GumboStringPiece original_name;
  const char* value;
  GumboStringPiece original_value;
  GumboSourcePosition name_start;
  GumboSourcePosition name_end;
  GumboSourcePosition value_start;
  GumboSourcePosition value_end;
} GumboAttribute;

typedef enum {
  GUMBO_NODE_DOCUMENT,
  GUMBO_NODE_ELEMENT,
  GUMBO_NODE_TEXT,
  GUMBO_NODE_CDATA,
  GUMBO_NODE_COMMENT,
  GUMBO_NODE_WHITESPACE,
  GUMBO_NODE_TEMPLATE
} GumboNodeType;

typedef enum {
  GUMBO_DOCTYPE_NO_QUIRKS,
  GUMBO_DOCTYPE_QUIRKS,
  GUMBO_DOCTYPE_LIMITED_QUIRKS
} GumboQuirksModeEnum;

typedef enum {
  GUMBO_NAMESPACE_HTML,
  GUMBO_NAMESPACE_SVG,
  GUMBO_NAMESPACE_MATHML
} GumboNamespaceEnum;

typedef struct {
  GumboVector /* GumboNode* */ children;
  bool has_doctype;
  const char* name;
  const char* public_identifier;
  const char* system_identifier;
  GumboQuirksModeEnum doc_type_quirks_mode;
} GumboDocument;

typedef struct {
  const char* text;
  GumboStringPiece original_text;
  GumboSourcePosition start_pos;
} GumboText;

typedef struct {
  GumboVector /* GumboNode* */ children;
  GumboTag tag;
  const char* name;
  GumboNamespaceEnum tag_namespace;
  GumboStringPiece original_tag;
  GumboStringPiece original_end_tag;
  GumboSourcePosition start_pos;
  GumboSourcePosition end_pos;
  GumboVector /* GumboAttribute* */ attributes;
} GumboElement;

struct GumboInternalNode {
  GumboNodeType type;
  GumboNode* parent;
  unsigned int index_within_parent;
  GumboParseFlags parse_flags;
  union {
    GumboDocument document;  // For GUMBO_NODE_DOCUMENT.
    GumboElement element;    // For GUMBO_NODE_ELEMENT.
    GumboText text;          // For everything else.
  } v;
};

typedef struct GumboInternalOptions {
  int tab_stop;
  bool stop_on_first_error;
  int max_attributes;
  unsigned int max_tree_depth;
  int max_errors;
  const char* fragment_context;
  GumboNamespaceEnum fragment_namespace;
  const char* fragment_encoding;
  GumboQuirksModeEnum quirks_mode;
  bool fragment_context_has_form_ancestor;
  bool parse_noscript_content_as_text;
} GumboOptions;

typedef enum {
  GUMBO_STATUS_OK,
  GUMBO_STATUS_TREE_TOO_DEEP,
  GUMBO_STATUS_TOO_MANY_ATTRIBUTES,
  GUMBO_STATUS_OUT_OF_MEMORY,
} GumboOutputStatus;

typedef struct GumboInternalOutput {
  GumboNode* document;
  GumboNode* root;
  GumboVector /* GumboError */ errors;
  bool document_error;
  GumboOutputStatus status;
} GumboOutput;

