// Construct a new GumboStringPiece with a stable backing buffer when non-empty.
GumboStringPiece *piece = new GumboStringPiece();
unsigned int make_empty = (*FUZZ_PARAM(unsigned int)) & 1u;
if (make_empty) {
  piece->data = NULL;
  piece->length = 0u;
} else {
  std::string s = FUZZ_PARAM_STR();
  if (s.size() > 512) { s.resize(512); } // keep small for perf
  // Ensure non-zero length for the non-empty branch; if fuzz gave empty, force a byte.
  if (s.empty()) { s.push_back('x'); }
  // Allocate a heap std::string to keep the memory alive beyond this call.
  std::string* holder = new std::string(s);
  piece->data = holder->data();
  piece->length = holder->size();
  // Attach the holder so later stubs (e.g., tag slicing) have a valid backing store.
  FUZZ_SET_ATTR_PTR(piece, "backing_str_ptr", (void*)holder);
  FUZZ_SET_ATTR_PTR(piece, "backing_str_data", (void*)piece->data);
  FUZZ_SET_ATTR_INT(piece, "backing_str_length", (int)piece->length);
}
// piece is fully initialized and safe to use with Gumbo string APIs.

// Build a GumboVector containing pointers (often GumboAttribute*) with valid invariants.
GumboVector *vector = new GumboVector();
unsigned int cap = (*FUZZ_PARAM(unsigned int) % 8u) + 1u; // [1,8]
vector->capacity = cap;
vector->length = *FUZZ_PARAM(unsigned int) % (cap + 1u); // [0,cap]
vector->data = (void**)calloc(vector->capacity, sizeof(void*));
if (!vector->data) { FUZZ_BAIL(); }
// Populate entries up to length. Prefer creating valid GumboAttribute objects for interoperability
// with gumbo_get_attribute; mix in NULLs to exercise not-found paths.
for (unsigned int i = 0; i < vector->length; ++i) {
  unsigned int make_null = (*FUZZ_PARAM(unsigned int)) & 1u;
  if (make_null) {
    vector->data[i] = NULL;
    continue;
  }
  // Allocate a GumboAttribute and initialize fields.
  GumboAttribute* attr = new GumboAttribute();
  attr->attr_namespace = (GumboAttributeNamespaceEnum)(*FUZZ_PARAM(unsigned int) % 4u);
  // Build name/value strings with stable backing storage.
  std::string name = FUZZ_PARAM_STR();
  if (name.size() > 64) { name.resize(64); }
  if (name.empty()) { name = "x"; }
  std::string value = FUZZ_PARAM_STR();
  if (value.size() > 128) { value.resize(128); }
  // Holders to preserve lifetime.
  std::string* name_holder = new std::string(name);
  std::string* value_holder = new std::string(value);
  // NUL-terminated views for attr->name/value.
  name_holder->push_back('\0');
  value_holder->push_back('\0');
  attr->name = name_holder->c_str();
  attr->value = value_holder->c_str();
  // original_name/value are string pieces pointing into holders without the terminal NUL.
  attr->original_name.data = name_holder->data();
  attr->original_name.length = name_holder->size() ? (name_holder->size() - 1) : 0;
  if (attr->original_name.length == 0) { attr->original_name.data = NULL; }
  attr->original_value.data = value_holder->data();
  attr->original_value.length = value_holder->size() ? (value_holder->size() - 1) : 0;
  if (attr->original_value.length == 0) { attr->original_value.data = NULL; }
  // Source positions: use monotonic offsets for start/end pairs.
  size_t base = (size_t)(*FUZZ_PARAM(unsigned int) % 1000u);
  attr->name_start.line = 1u; attr->name_start.column = 1u; attr->name_start.offset = base;
  attr->name_end.line = 1u; attr->name_end.column = (unsigned int)(attr->original_name.length + 1u); attr->name_end.offset = base + attr->original_name.length;
  attr->value_start.line = 1u; attr->value_start.column = 1u; attr->value_start.offset = base + 1u;
  attr->value_end.line = 1u; attr->value_end.column = (unsigned int)(attr->original_value.length + 1u); attr->value_end.offset = base + 1u + attr->original_value.length;
  // Attach holders to the attribute object so lifetimes persist.
  FUZZ_SET_ATTR_PTR(attr, "name_holder", (void*)name_holder);
  FUZZ_SET_ATTR_PTR(attr, "value_holder", (void*)value_holder);
  // Store into the vector.
  vector->data[i] = (void*)attr;
}
// Ensure invariants expected by users of GumboVector.
if (vector->length > vector->capacity) { FUZZ_BAIL(); }
if (vector->length > 0 && vector->data == NULL) { FUZZ_BAIL(); }
// Vector ready for use with gumbo_vector_index_of and gumbo_get_attribute.

