import random
import string
from typing import List

# This generator produces valid UTF-8 HTML inputs tailored for gumbo_parse and
# gumbo_parse_with_options fuzzers. It aims to exercise:
# - Doctype variations and quirks mode computation
# - HTML, SVG, MathML namespaces
# - Attributes (including boolean, duplicated names, namespaces like xlink:)
# - Various elements including void elements and rawtext/rcdata elements
# - Comments, CDATA (in foreign content), script/style contents
# - Entities, whitespace, unusual but valid constructs
# - Fragment-like bodies without full html/head/body
# It keeps size under 4096 bytes and uses only valid UTF-8.

VOID_ELEMENTS = [
    'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'
]

BLOCK_ELEMENTS = [
    'div','section','article','nav','aside','main','header','footer','p','ul','ol','li','table','tr','td','th','tbody','thead','tfoot'
]

INLINE_ELEMENTS = [
    'span','a','em','strong','i','b','u','mark','small','sup','sub','code','kbd','var','samp','q','cite','time','data'
]

RAWTEXT_ELEMENTS = ['style']
RCDATA_ELEMENTS = ['title', 'textarea']
FOREIGN_SVG = [
    'svg','g','defs','desc','foreignObject','circle','rect','path','text','tspan','image','use'
]
FOREIGN_MATHML = ['math','mi','mo','mn','ms','mtext']

GLOBAL_ATTRS = [
    'id','class','dir','hidden','lang','title','tabindex','accesskey','draggable'
]
EVENT_ATTRS = ['onclick','onload','onerror']
BOOL_ATTRS = ['disabled','checked','selected','readonly','multiple','required','autofocus']
URL_ATTRS = ['href','src','action','formaction']
NS_ATTRS = ['xlink:href','xml:lang','xmlns','xmlns:xlink']

UNICODE_WORDS = [
    'naïve','café','résumé','mañana','日本語','한국어','русский','العربية','हिन्दी','🙂','⚙️','©️','™️'
]

ENTITIES = ['&amp;','&lt;','&gt;','&quot;','&apos;','&copy;','&trade;','&#169;','&#x1F642;']

DOCTYPES = [
    '<!DOCTYPE html>',
    '<!DOCTYPE HTML>',
    '<!doctype html>',
    '<!DOCTYPE html PUBLIC "-//W3C//DTD HTML 4.01 Transitional//EN" "http://www.w3.org/TR/html4/loose.dtd">',
    '<!DOCTYPE html PUBLIC "-//W3C//DTD HTML 4.01//EN" "http://www.w3.org/TR/html4/strict.dtd">',
    '<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">',
    '<!DOCTYPE html SYSTEM "about:legacy-compat">',
]

def _rand_choice(rnd: random.Random, seq: List[str]) -> str:
    return rnd.choice(seq)

def _rand_ident(rnd: random.Random, min_len=3, max_len=10) -> str:
    letters = string.ascii_letters + string.digits + '-_'
    n = rnd.randint(min_len, max_len)
    return ''.join(rnd.choice(letters) for _ in range(n))

def _rand_text(rnd: random.Random, max_len=120) -> str:
    parts = []
    while len(''.join(parts)) < max_len:
        choice = rnd.randint(0, 6)
        if choice == 0:
            parts.append(_rand_ident(rnd, 1, 8))
        elif choice == 1:
            parts.append(_rand_choice(rnd, UNICODE_WORDS))
        elif choice == 2:
            parts.append(' ' * rnd.randint(1, 3))
        elif choice == 3:
            parts.append(_rand_choice(rnd, ENTITIES))
        elif choice == 4:
            parts.append('\n' if rnd.random() < 0.5 else '\t')
        elif choice == 5:
            parts.append('.,;:!?')
        else:
            parts.append('-')
        if rnd.random() < 0.15:
            break
    return ''.join(parts)

def _attr_pair(rnd: random.Random) -> str:
    name_pool = GLOBAL_ATTRS + EVENT_ATTRS + URL_ATTRS + NS_ATTRS + [
        _rand_ident(rnd), _rand_ident(rnd)
    ]
    name = _rand_choice(rnd, name_pool)
    # Boolean attribute occasionally omitted value
    if name in BOOL_ATTRS or rnd.random() < 0.15:
        return name
    # Value
    val_choices = [
        _rand_text(rnd, 30),
        _rand_choice(rnd, UNICODE_WORDS),
        _rand_choice(rnd, ENTITIES),
        f"{_rand_ident(rnd)} {_rand_ident(rnd)}",
    ]
    if name in URL_ATTRS or name.endswith(':href'):
        val_choices += ['http://example.com/', 'https://example.org/path?x=1&y=2', 'mailto:test@example.com']
    if name.startswith('xmlns'):
        val_choices += ['http://www.w3.org/2000/svg', 'http://www.w3.org/1999/xlink', 'http://www.w3.org/1999/xhtml']
    value = _rand_choice(rnd, val_choices)
    quote = rnd.choice(['"', "'"])
    return f"{name}={quote}{value}{quote}"

def _open_tag(rnd: random.Random, name: str, attrs_min=0, attrs_max=4) -> str:
    attrs = []
    k = rnd.randint(attrs_min, attrs_max)
    for _ in range(k):
        attrs.append(_attr_pair(rnd))
    # Occasionally duplicate an attribute to test first-match behavior
    if attrs and rnd.random() < 0.2:
        attrs.append(attrs[0].split('=')[0])
    space = ' ' if attrs else ''
    return f"<{name}{space}{' '.join(attrs) if attrs else ''}>"

def _close_tag(name: str) -> str:
    return f"</{name}>"

def _comment(rnd: random.Random) -> str:
    body = _rand_text(rnd, 40).replace('--', '- -')
    return f"<!--{body}-->"

def _script(rnd: random.Random) -> str:
    # Keep it simple; avoid '</script' literal confusion by embedding CDATA-style content sometimes
    if rnd.random() < 0.5:
        content = f"// {_rand_text(rnd, 60)}\nvar x=1;/*{_rand_text(rnd, 20)}*/"
    else:
        content = f"/*<![CDATA[*/ var a = '{_rand_text(rnd, 20)}'; /*]]>*/"
    return _open_tag(rnd, 'script', 0, 2) + content + _close_tag('script')

def _style(rnd: random.Random) -> str:
    css = f"body{{color:#333}} .{_rand_ident(rnd)}{{display:block}}"
    return _open_tag(rnd, 'style', 0, 2) + css + _close_tag('style')

def _table(rnd: random.Random) -> str:
    rows = []
    for _ in range(rnd.randint(1, 3)):
        cells = ''.join(f"<td>{_rand_text(rnd, 20)}</td>" for __ in range(rnd.randint(1, 3)))
        rows.append(f"<tr>{cells}</tr>")
    return f"<table>{''.join(rows)}</table>"

def _list(rnd: random.Random) -> str:
    items = ''.join(f"<li>{_rand_text(rnd, 25)}</li>" for _ in range(rnd.randint(2, 6)))
    tag = 'ol' if rnd.random() < 0.5 else 'ul'
    return f"<{tag}>{items}</{tag}>"

def _svg_fragment(rnd: random.Random) -> str:
    # Include xmlns to keep it valid, though parser infers in foreign content
    attrs = ["xmlns='http://www.w3.org/2000/svg'", "xmlns:xlink='http://www.w3.org/1999/xlink'"]
    parts = [f"<svg {' '.join(attrs)}>"]
    parts.append(f"<desc>{_rand_text(rnd, 20)}</desc>")
    if rnd.random() < 0.6:
        parts.append(f"<circle cx='50' cy='50' r='{random.randint(10,80)}'></circle>")
    if rnd.random() < 0.6:
        parts.append(f"<image xlink:href='http://example.com/{_rand_ident(rnd)}.png'></image>")
    parts.append("</svg>")
    return ''.join(parts)

def _mathml_fragment(rnd: random.Random) -> str:
    return f"<math xmlns='http://www.w3.org/1998/Math/MathML'><mi>x</mi><mo>=</mo><mn>{rnd.randint(1,9)}</mn></math>"

def _body_content(rnd: random.Random, budget: int) -> str:
    chunks: List[str] = []
    generators = [
        lambda: _comment(rnd),
        lambda: _script(rnd),
        lambda: _style(rnd),
        lambda: _table(rnd),
        lambda: _list(rnd),
        lambda: _svg_fragment(rnd),
        lambda: _mathml_fragment(rnd),
        lambda: _open_tag(rnd, _rand_choice(rnd, BLOCK_ELEMENTS), 0, 3) + _rand_text(rnd, 80) + _close_tag(_rand_choice(rnd, BLOCK_ELEMENTS)),
        lambda: _open_tag(rnd, _rand_choice(rnd, INLINE_ELEMENTS), 0, 3) + _rand_text(rnd, 40) + _close_tag(_rand_choice(rnd, INLINE_ELEMENTS)),
    ]
    while budget > 0 and len(''.join(chunks)) < budget:
        g = _rand_choice(rnd, generators)
        piece = g()
        # Avoid runaway growth
        if len(piece) > budget - len(''.join(chunks)):
            piece = piece[: max(0, budget - len(''.join(chunks)))]
        chunks.append(piece)
        if rnd.random() < 0.2:
            break
    return ''.join(chunks)

def _doctype(rnd: random.Random) -> str:
    # Pick a doctype; occasionally add whitespace or comments around
    dt = _rand_choice(rnd, DOCTYPES)
    pre = ''
    post = ''
    if rnd.random() < 0.3:
        pre = _comment(rnd) + '\n'
    if rnd.random() < 0.3:
        post = '\n' + _comment(rnd)
    return pre + dt + post

def _head(rnd: random.Random) -> str:
    parts = []
    if rnd.random() < 0.7:
        parts.append(f"<meta charset=\"utf-8\">")
    if rnd.random() < 0.7:
        parts.append(f"<title>{_rand_text(rnd, 24)}</title>")
    if rnd.random() < 0.5:
        parts.append(f"<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">")
    if rnd.random() < 0.5:
        parts.append(f"<link rel=\"stylesheet\" href=\"https://example.org/{_rand_ident(rnd)}.css\">")
    if rnd.random() < 0.4:
        parts.append(_style(rnd))
    return '<head>' + ''.join(parts) + '</head>'

def _html_document(rnd: random.Random, target_bytes: int) -> str:
    parts = []
    if rnd.random() < 0.9:
        parts.append(_doctype(rnd) + "\n")
    # Optional attributes on html/body
    html_open = _open_tag(rnd, 'html', 0, 3)
    parts.append(html_open)
    if rnd.random() < 0.9:
        parts.append(_head(rnd))
    body_open = _open_tag(rnd, 'body', 0, 4)
    parts.append(body_open)
    body_budget = max(0, target_bytes - len(''.join(parts)) - 16)
    parts.append(_body_content(rnd, min(body_budget, 1500)))
    parts.append('</body></html>')
    return ''.join(parts)

def _fragment_variants(rnd: random.Random, target_bytes: int) -> str:
    # Generate a variety of valid fragments without full html wrapper
    choices = []
    choices.append(_list(rnd))
    choices.append(_table(rnd))
    choices.append(_svg_fragment(rnd))
    choices.append(_mathml_fragment(rnd))
    choices.append(_script(rnd))
    # Mix inline and block
    s = []
    for _ in range(rnd.randint(1, 4)):
        s.append(_rand_choice(rnd, choices))
    # Add some plain text around
    if rnd.random() < 0.7:
        s.insert(0, _rand_text(rnd, 60))
    if rnd.random() < 0.7:
        s.append(_rand_text(rnd, 60))
    out = ''.join(s)
    if len(out) > target_bytes:
        out = out[:target_bytes]
    return out

def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    # Choose mode: full document or fragment
    target_size = rnd.randint(200, 1800)
    mode = rnd.random()
    if mode < 0.6:
        txt = _html_document(rnd, target_size)
    elif mode < 0.85:
        txt = _fragment_variants(rnd, target_size)
    else:
        # Minimal but interesting valid UTF-8 buffers: plain text with entities and comments
        txt = _comment(rnd) + '\n' + _rand_text(rnd, target_size)
    # Ensure under 4096 bytes
    if len(txt.encode('utf-8')) > 4096:
        txt = txt[:3000]
    return txt.encode('utf-8')
